    const body=await req.json(), {entity,action,args=[]}=body;
    if(!Array.isArray(args))fail('Invalid arguments',400);
    if(!caller && !(entity==='Track' && ['read','videoPlayback'].includes(action))) fail('Sign in to continue',401);
